package main

const jsPrivateResearchSchedule = `
function syncPrivateScheduleEditor(selected=null){const form=$('research-schedule-form'),enabled=form.elements.private_enabled.checked,select=form.elements.private_selections;const previous=selected===null?[...select.selectedOptions].map(o=>JSON.parse(o.value)):selected,keys=new Set(previous.map(v=>key(v)));select.replaceChildren();const rows=myModels.filter(v=>v.enabled&&v.state==="ACTIVE"&&chatOperation(targetOperation(v)));for(const v of rows){const exact=scope(v);option(select,JSON.stringify(exact),(v.display_name||v.model_id)+' · '+(providers.find(p=>p.id===v.provider_id)?.name||v.provider_id)+' / '+connectionLabel(v)+' / '+v.endpoint);select.lastChild.selected=keys.delete(key(exact));}for(const v of previous)if(keys.has(key(v))){option(select,JSON.stringify(v),v.model_id+' / '+v.provider_id+' / '+v.account_id+' / '+v.credential_id+' · 待確認');select.lastChild.selected=true;}const fieldset=$('research-schedule-private-fields');fieldset.hidden=!enabled;fieldset.disabled=!enabled;}
async function reviewPrivateResearchSchedule(v){const box=modal('確認私人研究排程'),ticket=detailVersion;box.append(el('p','讀取目前模型連線與來源…'));const read=async()=>{try{const review=await api('/research/schedules/review?id='+encodeURIComponent(v.id));if(ticket!==detailVersion)return;box.replaceChildren();box.append(el('p','啟用後，目前服務會依排程使用以下連線。這可能消耗免費額度或產生費用；只核准這次顯示的來源與 Key 版本，變更後需要重新確認。'));for(const row of review.scopes){const s=row.selection;item(box,(models.find(m=>m.provider_id===s.provider_id&&m.id===s.model_id)?.display_name||s.model_id)+' · '+connectionLabel(s),row.origin+' · '+row.operation+' · Key 版本 '+row.credential_version+' · '+s.provider_id+' / '+s.account_id+' / '+s.credential_id+(s.group?' / '+s.group:''));}const p=review.private;item(box,'研究上限',review.options.budget+' HTTP / 輪 · '+review.options.probe_budget+' 推論 / 輪 · 每日 '+p.daily_inferences+' 次／'+resourceLimitText(p.daily_tokens)+' token／'+resourceLimitText(p.daily_usd)+' USD。');const problem=el('p');problem.setAttribute('role','status');box.append(problem);action(box,'更新確認範圍',read);box.append(el('p',p.resume_after_reset?'你已選擇每日重設後自動接續。':'用量達上限後停止，需要手動接續。'),el('p','日常已有有效觀測時優先重用。失敗、取消或缺回報保留預留；中斷推論不自動重送。全部研究、逐 Key 與共用池上限仍同時生效。'));action(box,'確認並啟用私人排程',async()=>{if(ticket!==detailVersion)return;const saved=await mutateResearchSchedule('/research/schedules/control',{id:v.id,revision:review.revision,action:'ENABLE',confirm_private:true,expected_private_fingerprint:review.fingerprint},()=>{if(ticket===detailVersion)$('detail').close();},'私人研究排程已啟用。');if(!saved&&ticket===detailVersion)problem.textContent='啟用未完成，請更新確認範圍後重試。';});}catch(e){if(ticket===detailVersion){box.replaceChildren();detailState(box,e.message,true,read);}}};await read();}
async function privateScheduleHistory(v){const box=modal(v.name+' · 私人核准紀錄'),ticket=detailVersion,list=el('div'),problem=el('p'),more=el('button','讀取更多私人核准');box.append(el('p','保留每次明確確認的範圍與預算，紀錄不授予其他裝置執行權。'),list,problem,more);let before=0,loading=false;const read=async()=>{if(loading)return;loading=true;more.disabled=true;try{const response=await api('/research/schedules/private-history?id='+encodeURIComponent(v.id)+(before?'&before='+before:''));if(ticket!==detailVersion)return;for(const row of response.history){const d=row.definition,p=d.private;item(list,'核准版本 '+row.revision+' · '+new Date(row.approved_at).toLocaleString(),d.options.selections.map(s=>s.model_id+' / '+s.provider_id+' / '+s.account_id+' / '+s.credential_id+' / '+s.endpoint).join('；')+' · 每日 '+p.daily_inferences+' 次／'+resourceLimitText(p.daily_tokens)+' token／'+resourceLimitText(p.daily_usd)+' USD');}if(!response.history.length&&!before)item(list,'尚無私人核准','私人排程啟用前需要明確確認。');before=response.next_before;more.hidden=!before;problem.textContent='';}catch(e){if(ticket===detailVersion)problem.textContent=e.message;}finally{loading=false;more.disabled=false;}};more.addEventListener('click',read);await read();}

`
